steps.script:
var main = tree.root.get_node("Main")
TerrainManager.set_meta("tac_saved_layout", TerrainManager.current_layout)
TerrainManager.load_terrain_layout("take_and_hold_vs_reconnaissance_1")
var units = GameState.state["units"]
var px = 40.0
for uid in units:
	if uid != "U_THUNDERWOLF_CAVALRY_B" and uid != "U_GRETCHIN_C":
		for m in units[uid].get("models", []):
			m["alive"] = false
		continue
	units[uid]["flags"] = {}
	units[uid]["status"] = GameStateData.UnitStatus.DEPLOYED
var cav = units["U_THUNDERWOLF_CAVALRY_B"]["models"]
for i in range(cav.size()):
	cav[i]["alive"] = (i == 0)
cav[0]["position"] = {"x": 31.5 * px, "y": 43.0 * px}
cav[0]["rotation"] = 0.0
PhaseManager.get_current_phase_instance().update_local_state(GameState.create_snapshot())
main._recreate_unit_visuals()
main.movement_controller._refresh_unit_list()
return "ok"

var m = GameState.get_unit("U_THUNDERWOLF_CAVALRY_B")["models"][0].duplicate(true)
m["position"] = Vector2(27.0, 43.0) * 40.0
var kws = GameState.get_unit("U_THUNDERWOLF_CAVALRY_B")["meta"]["keywords"]
var with_mobile = str(TerrainManager.solid_terrain_endpoint_blocker_11e(m, kws, ["MOBILE"]))
var without = str(TerrainManager.solid_terrain_endpoint_blocker_11e(m, kws))
var path = TerrainManager.can_move_through_11e(kws, Vector2(31.5, 43.0) * 40.0, Vector2(22.5, 43.0) * 40.0, ["MOBILE"], GameState.get_unit("U_THUNDERWOLF_CAVALRY_B")["models"][0])
print("[%s] end on generator-11's top: blocker with MOBILE='%s' without='%s' | path across it with MOBILE allowed=%s" % ["mobile_cannot_end_on_dense_feature_11e", with_mobile, without, str(path.allowed)])
return "%s|%s|%s" % [with_mobile, without, str(path.allowed)]

var u = GameState.get_unit("U_THUNDERWOLF_CAVALRY_B")
var md = PhaseManager.get_current_phase_instance().active_moves.get("U_THUNDERWOLF_CAVALRY_B", {})
var kws = PhaseManager.get_current_phase_instance()._terrain_rule_keywords("U_THUNDERWOLF_CAVALRY_B", md)
print("[%s] after FENRISIAN FEROCITY: flag=%s mode=%s terrain keywords=%s" % ["mobile_cannot_end_on_dense_feature_11e", str(u.get("flags", {}).get("ork11e_mobile", false)), str(md.get("mode", "")), str(kws)])
return "%s|%s|%s" % [str(u.get("flags", {}).get("ork11e_mobile", false)), str(md.get("mode", "")), str("MOBILE" in kws)]

var md = PhaseManager.get_current_phase_instance().active_moves.get("U_THUNDERWOLF_CAVALRY_B", {})
var staged = md.get("staged_moves", [])
var m = GameState.get_unit("U_THUNDERWOLF_CAVALRY_B")["models"][0]
print("[%s] after the drop on the generator top: staged=%d, model at (%.2f, %.2f)in" % ["mobile_cannot_end_on_dense_feature_11e", staged.size(), float(m.position.x) / 40.0, float(m.position.y) / 40.0])
return "%d|%s" % [staged.size(), str(absf(float(m.position.x) / 40.0 - 31.5) < 0.1)]

var md = PhaseManager.get_current_phase_instance().active_moves.get("U_THUNDERWOLF_CAVALRY_B", {})
var staged = md.get("staged_moves", [])
if staged.is_empty():
	return "not staged"
var d = staged[0].get("dest")
var booked = float(md.get("model_distances", {}).values()[0]) if not md.get("model_distances", {}).is_empty() else -1.0
print("[%s] staged at (%.2f, %.2f)in, booked %.2fin (%s)" % ["mobile_cannot_end_on_dense_feature_11e", d.x / 40.0, d.y / 40.0, booked, str(md.get("model_distances", {}))])
return "%s|%s" % [str(absf(d.x / 40.0 - 22.5) < 0.3 and absf(d.y / 40.0 - 43.0) < 0.3), str(absf(booked - 9.0) < 0.3)]

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_log_file_path(), FileAccess.READ)
if f == null:
	return -1
var n = 0
var bad = []
while not f.eof_reached():
	var l = f.get_line()
	if l.contains("[ERROR"):
		n += 1
		bad.append(l)
print("[mobile_cannot_end_on_dense_feature_11e log] ERROR lines = ", n, " ", bad.slice(0, 3))
return n

if TerrainManager.has_meta("tac_saved_layout"):
	var lay = str(TerrainManager.get_meta("tac_saved_layout"))
	TerrainManager.remove_meta("tac_saved_layout")
	if lay != "":
		TerrainManager.load_terrain_layout(lay)
return true
